package me.danialisntcool.factionfriction.faction;import java.util.*;public class Faction {public UUID id=UUID.randomUUID();public String name;public WarData war=new WarData();public Map<UUID,FactionRank> members=new HashMap<>();public Set<UUID> allies=new HashSet<>();public Set<Long> claims=new HashSet<>(),capital=new HashSet<>();public FactionTier tier=FactionTier.TEAM;public long allianceCooldown;public Faction(String n){name=n;}public UUID getId(){return id;}public String getName(){return name;}public String getSlug(){return name;}public int getClaimCount(){return claims.size();}public void setTier(FactionTier tier){this.tier=tier;}public int getColor(){return 0x777744;}public Map<UUID,FactionRank> getMembers(){return members;}public WarData getWarData(){return war;}public Set<UUID> getAllies(){return allies;}public long getAllianceBreakCooldownEnd(UUID enemy){return allianceCooldown;}public void addConflictHistory(String s){}public FactionTier getTier(){return tier;}public Set<Long> getClaimedChunks(){return claims;}public Set<Long> getCapitalChunks(){return capital;}public boolean hasCapital(){return !capital.isEmpty();}}